css:
/* Retro Desk — a fully independent Ground theme. No Iris chrome, no glass. */
:root, .shell {
  --ground-radius: 0px;
  --window-radius: 0px;
  --window-content-radius: 0px;
  --window-control-radius: 0px;
  --dock-radius: 0px;
  --dock-item-radius: 0px;
  --group-radius: 0px;
  --toolbar-radius: 0px;
  --command-palette-radius: 0px;
  --menu-radius: 0px;
  --menu-item-radius: 0px;
  --dock-background: var(--rumahl-ui-color-panel-background);
  --dock-surface: var(--rumahl-ui-color-panel-background);
  --dock-surface-border: 2px solid var(--rumahl-ui-color-outline);
  --dock-surface-shadow: 4px 4px 0 var(--rumahl-ui-color-outline);
  --dock-sheen: none;
  --dock-shadow: none;
  --label-ink: var(--rumahl-ui-color-text-primary);
  --adaptive-color-duration: 0ms;
  --menu-background: var(--rumahl-ui-color-surface-strong);
  --menu-border: 2px solid var(--rumahl-ui-color-outline);
  --menu-shadow: 4px 4px 0 var(--rumahl-ui-color-outline);
  --menu-backdrop: none;
  --menu-item-hover: color-mix(in srgb, var(--rumahl-ui-color-accent) 18%, transparent);
  --widget-background: var(--rumahl-ui-color-surface-strong);
  --widget-border: 2px solid var(--rumahl-ui-color-outline);
  --widget-shadow: 4px 4px 0 var(--rumahl-ui-color-outline);
  --widget-ink: var(--rumahl-ui-color-text-primary);
  --widget-muted: var(--rumahl-ui-color-text-muted);
  --glass-solid-background: var(--rumahl-ui-color-surface-strong);
  --motion-feedback-duration: 0ms;
  --motion-surface-duration: 0ms;
  --motion-hover-duration: 0ms;
  --motion-control-duration: 0ms;
  --motion-press-duration: 0ms;
  --motion-state-duration: 0ms;
  --motion-easing-standard: linear;
  --motion-easing-spring: linear;
  --motion-spring-bouncy: linear;
  --motion-spring-soft: linear;
  --motion-spring-snap: linear;
}
.shell {
  background: var(--rumahl-ui-color-canvas-background);
  color: var(--rumahl-ui-color-text-primary);
  font-family: var(--rumahl-ui-typography-family);
}
.shell .wallpaper {
  background: var(--rumahl-ui-texture-wallpaper);
}
.shell :is(.topbar__island, .menubar, .taskbar) {
  background: var(--rumahl-ui-color-panel-background);
  border: 2px solid var(--rumahl-ui-color-outline);
  border-radius: 0;
  box-shadow: 3px 3px 0 var(--rumahl-ui-color-outline);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  color: var(--rumahl-ui-color-text-primary);
}
.shell .shell-window {
  background: var(--rumahl-ui-color-surface-strong);
  border: 2px solid var(--rumahl-ui-color-outline);
  border-radius: 0;
  box-shadow: 6px 6px 0 var(--rumahl-ui-color-outline);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  color: var(--rumahl-ui-color-text-primary);
}
.shell .shell-window__titlebar {
  background: var(--rumahl-ui-color-panel-background);
  border-bottom: 2px solid var(--rumahl-ui-color-outline);
  color: var(--rumahl-ui-color-text-primary);
}
.shell .shell-window__controls button,
.shell .window-control {
  border: 2px solid var(--rumahl-ui-color-outline);
  border-radius: 0;
  background: var(--rumahl-ui-color-surface-strong);
  color: var(--rumahl-ui-color-text-primary);
  box-shadow: 1px 1px 0 var(--rumahl-ui-color-outline);
}
.shell .shell-window__controls button:hover,
.shell .window-control:hover {
  background: var(--rumahl-ui-color-accent);
  color: var(--rumahl-ui-color-on-accent);
}
.shell .os-dock :is(.dock-item, .dock-icon, button, a) {
  border: 1px solid var(--rumahl-ui-color-outline);
  border-radius: 0;
  background: var(--rumahl-ui-color-surface-strong);
  box-shadow: 2px 2px 0 var(--rumahl-ui-color-outline);
}
.shell .os-dock :is(.dock-item, .dock-icon, button, a):hover {
  background: var(--rumahl-ui-color-panel-background);
}
.shell .desktop-widget {
  border: 2px solid var(--rumahl-ui-color-outline);
  border-radius: 0;
  box-shadow: 4px 4px 0 var(--rumahl-ui-color-outline);
}
.shell .desktop-icon__art {
  border: 2px solid var(--rumahl-ui-color-outline);
  border-radius: 0;
  background: var(--rumahl-ui-color-surface-strong);
  box-shadow: 2px 2px 0 var(--rumahl-ui-color-outline);
}
.shell .desktop-icon__label {
  padding: 1px 3px;
  border: 1px solid var(--rumahl-ui-color-outline);
  border-radius: 0;
  background: var(--rumahl-ui-color-surface-strong);
  text-shadow: none;
}
.shell .desktop-icon:hover,
.shell .desktop-icon.is-selected {
  border-color: var(--rumahl-ui-color-accent);
  background: color-mix(in srgb, var(--rumahl-ui-color-accent) 18%, transparent);
}
.shell .desktop-search {
  border: 2px solid var(--rumahl-ui-color-outline);
  border-radius: 0;
  background: var(--rumahl-ui-color-surface-strong);
  color: var(--rumahl-ui-color-text-primary);
  text-shadow: none;
}
.shell :is(.settings-group, .rumahl-group) {
  border: 2px solid var(--rumahl-ui-color-outline);
  border-radius: 0;
  background: var(--rumahl-ui-color-surface-strong);
  box-shadow: 4px 4px 0 var(--rumahl-ui-color-outline);
}
.shell .settings-nav__row.is-active,
.shell .files-nav.is-active {
  background: var(--rumahl-ui-color-accent);
  color: var(--rumahl-ui-color-on-accent);
}
.shell .files-app__sidebar {
  background: var(--rumahl-ui-color-panel-background);
  border-right: 2px solid var(--rumahl-ui-color-outline);
}
.shell .files-nav {
  border-radius: 0;
}
.shell .files-view-switch,
.shell .files-view-switch__thumb,
.shell .files-crumbs__root,
.shell .files-icon-btn {
  border-radius: 0;
}
.shell :is(.store-grid-card, .store-edit-card, .store-card, .store-product-hero) {
  border: 2px solid var(--rumahl-ui-color-outline);
  border-radius: 0;
  background: var(--rumahl-ui-color-surface-strong);
  box-shadow: 4px 4px 0 var(--rumahl-ui-color-outline);
}
.shell :is(.store-grid-card__media, .store-shot, .store-art, .store-cover) {
  border-radius: 0;
}
.shell :is(.btn, .rumahl-input, input:not([type="checkbox"]):not([type="radio"]), select, textarea) {
  border: 2px solid var(--rumahl-ui-color-outline);
  border-radius: 0;
  background: var(--rumahl-ui-color-surface-strong);
  color: var(--rumahl-ui-color-text-primary);
  box-shadow: 2px 2px 0 var(--rumahl-ui-color-outline);
}
.shell .btn:hover {
  background: var(--rumahl-ui-color-panel-background);
}
.shell .btn:active {
  box-shadow: none;
  transform: translate(2px, 2px);
}
.shell :is(.section-title, .settings-section-title, .settings-content .section-title) {
  font-family: var(--rumahl-ui-typography-display);
  color: var(--rumahl-ui-color-accent);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.shell :focus-visible {
  outline: 3px solid var(--rumahl-ui-color-accent);
  outline-offset: 2px;
}
.shell ::selection {
  background: var(--rumahl-ui-color-accent);
  color: var(--rumahl-ui-color-on-accent);
}
